"""Object storage abstraction. Keys are generated by the application, never user filenames.

Flat keys (`<32 hex>[.ext]`) hold uploaded originals and derivatives. Namespaced keys
(`probs/…`, `crops/…`, `embeddings/…`, `models/…`) hold pipeline artifacts. Local storage
maps keys onto MEDIA_ROOT; a GCS backend implements the same methods.
"""
import re
from pathlib import Path
from typing import Protocol
from .config import MEDIA_ROOT

FLAT_KEY = re.compile(r'[a-f0-9]{32}(?:\.[a-z0-9]+)?')
NAMESPACED_KEY = re.compile(r'(?:probs|crops|embeddings|models)(?:/[a-z0-9][a-z0-9._-]{0,99}){1,3}')


def valid_key(key: str) -> bool:
    return bool(FLAT_KEY.fullmatch(key) or (NAMESPACED_KEY.fullmatch(key) and '..' not in key))


class ObjectStore(Protocol):
    def put_bytes(self, key: str, data: bytes) -> None: ...
    def get_bytes(self, key: str) -> bytes: ...
    def exists(self, key: str) -> bool: ...
    def delete(self, key: str) -> None: ...
    def list(self, prefix: str) -> list[str]: ...


class LocalStorage:
    def __init__(self, root: Path = MEDIA_ROOT):
        self.root = root
        self.root.mkdir(parents=True, exist_ok=True)

    def path(self, key: str) -> Path:
        if not valid_key(key):
            raise ValueError("Geçersiz storage anahtarı")
        path = self.root / key
        resolved_root = self.root.resolve()
        if path.is_symlink() or not path.resolve().is_relative_to(resolved_root) or \
                path.resolve().parent != (resolved_root / key).parent.resolve():
            raise ValueError("Geçersiz storage yolu")
        return path

    def put_bytes(self, key: str, data: bytes) -> None:
        path = self.path(key)
        path.parent.mkdir(parents=True, exist_ok=True)
        temp = path.with_name(path.name + '.part')
        temp.write_bytes(data)
        temp.replace(path)

    def get_bytes(self, key: str) -> bytes:
        return self.path(key).read_bytes()

    def exists(self, key: str) -> bool:
        return self.path(key).exists()

    def delete(self, key: str) -> None:
        self.path(key).unlink(missing_ok=True)

    def list(self, prefix: str) -> list[str]:
        base = self.root / prefix
        if not base.is_dir():
            return []
        return sorted(str(p.relative_to(self.root)) for p in base.rglob('*') if p.is_file() and not p.name.endswith('.part'))


def object_store() -> LocalStorage:
    return LocalStorage()
